/* 结算页初始化 */
function initCheckoutPage() {
  var app = document.getElementById('app');
  var items = Cart.getAll();

  if (items.length === 0) {
    app.innerHTML = renderHeader() + '<main class="container"><div class="empty-cart"><div class="icon">🛒</div><h2>购物车是空的</h2><a href="index.html" class="btn btn-primary">去购物</a></div></main>' + renderFooter();
    return;
  }

  var subtotal = Cart.getTotal();
  var shipping = subtotal >= 199 ? 0 : 15;
  var total = subtotal + shipping;
  var selectedPayment = 'wechat';

  function render() {
    var orderItemsHtml = items.map(function(item) {
      var p = PRODUCTS.find(function(pr) { return pr.id === item.id; });
      if (!p) return '';
      return '<div class="order-item"><div class="order-img">' + p.image + '</div><div class="order-info"><div class="order-name">' + p.name + '</div><div class="order-qty">x' + item.qty + '</div></div><div class="order-price">' + formatPrice(p.price * item.qty) + '</div></div>';
    }).join('');

    var paymentHtml = PAYMENT_METHODS.map(function(m) {
      return '<div class="payment-option' + (m.id === selectedPayment ? ' active' : '') + '" data-id="' + m.id + '">' +
        '<span class="payment-icon">' + m.icon + '</span>' +
        '<div><div class="payment-name">' + m.name + '</div><div class="payment-desc">' + m.desc + '</div></div>' +
        '<span class="payment-check">' + (m.id === selectedPayment ? '✓' : '') + '</span></div>';
    }).join('');

    app.innerHTML = renderHeader() +
      '<main class="container checkout-page"><h1 class="page-title">📋 确认订单</h1>' +
      '<div class="checkout-grid">' +
      '<div class="checkout-form">' +
      '<h2>收货信息</h2>' +
      '<div class="form-group"><label>收货人</label><input type="text" id="name" placeholder="请输入姓名"></div>' +
      '<div class="form-group"><label>手机号</label><input type="tel" id="phone" placeholder="请输入手机号"></div>' +
      '<div class="form-group"><label>收货地址</label><textarea id="address" placeholder="请输入详细地址"></textarea></div>' +
      '<div class="form-group"><label>备注</label><input type="text" id="note" placeholder="选填"></div>' +
      '<h2 style="margin-top:30px">支付方式</h2>' +
      '<div class="payment-options">' + paymentHtml + '</div>' +
      '</div>' +
      '<div><div class="cart-summary"><h3>订单详情</h3>' +
      '<div class="order-items">' + orderItemsHtml + '</div>' +
      '<div class="summary-row"><span>商品小计</span><span>' + formatPrice(subtotal) + '</span></div>' +
      '<div class="summary-row"><span>运费</span><span>' + (shipping === 0 ? '免运费' : formatPrice(shipping)) + '</span></div>' +
      '<div class="summary-row total"><span>应付金额</span><span>' + formatPrice(total) + '</span></div>' +
      '<button class="btn btn-primary btn-block" style="margin-top:20px" id="submitOrder">立即支付 ' + formatPrice(total) + '</button>' +
      '</div></div></div></main>' + renderFooter();

    bindEvents();
  }

  function bindEvents() {
    document.querySelectorAll('.payment-option').forEach(function(opt) {
      opt.addEventListener('click', function() {
        selectedPayment = this.getAttribute('data-id');
        render();
      });
    });

    document.getElementById('submitOrder').addEventListener('click', function() {
      var name = document.getElementById('name').value.trim();
      var phone = document.getElementById('phone').value.trim();
      var address = document.getElementById('address').value.trim();
      if (!name || !phone || !address) { showToast('请填写完整收货信息'); return; }
      processPayment(selectedPayment, total);
    });
  }

  render();
}

/* 处理支付 */
function processPayment(method, amount) {
  var app = document.getElementById('app');
  var methodInfo = PAYMENT_METHODS.find(function(m) { return m.id === method; });
  var orderId = 'DD' + Date.now().toString().slice(-8);

  if (method === 'cod') {
    // 货到付款直接下单成功
    Cart.clear();
    app.innerHTML = renderHeader() + '<main class="container"><div class="empty-cart" style="padding:80px 0">' +
      '<div class="icon">🎉</div>' +
      '<h2>下单成功！</h2>' +
      '<div class="order-success-info">' +
      '<p><strong>订单号：</strong>' + orderId + '</p>' +
      '<p><strong>支付方式：</strong>货到付款</p>' +
      '<p style="color:var(--text-secondary)">商品将在2-5个工作日内送达，请准备好现金</p>' +
      '</div>' +
      '<a href="index.html" class="btn btn-primary" style="margin-top:30px">继续购物</a>' +
      '</div></main>' + renderFooter();
    return;
  }

  // 在线支付 - 显示模拟支付页面
  app.innerHTML = renderHeader() + '<main class="container"><div class="payment-page">' +
    '<div class="payment-card">' +
    '<div class="payment-header">' + methodInfo.icon + ' ' + methodInfo.name + '</div>' +
    '<div class="payment-amount">¥' + amount.toFixed(2) + '</div>' +
    '<div class="payment-qr"><div class="qr-placeholder">📱<br>请使用' + methodInfo.name + '扫码支付</div></div>' +
    '<div class="payment-tips">演示模式：点击下方按钮模拟支付成功</div>' +
    '<button class="btn btn-primary btn-block" id="confirmPay">模拟支付成功</button>' +
    '<button class="btn btn-secondary btn-block" id="cancelPay" style="margin-top:10px">取消支付</button>' +
    '</div></div></main>' + renderFooter();

  document.getElementById('confirmPay').addEventListener('click', function() {
    Cart.clear();
    app.innerHTML = renderHeader() + '<main class="container"><div class="empty-cart" style="padding:80px 0">' +
      '<div class="icon">✅</div>' +
      '<h2>支付成功！</h2>' +
      '<div class="order-success-info">' +
      '<p><strong>订单号：</strong>' + orderId + '</p>' +
      '<p><strong>支付方式：</strong>' + methodInfo.name + '</p>' +
      '<p><strong>支付金额：</strong>¥' + amount.toFixed(2) + '</p>' +
      '<p style="color:var(--text-secondary)">商品将在2-5个工作日内发出</p>' +
      '</div>' +
      '<a href="index.html" class="btn btn-primary" style="margin-top:30px">继续购物</a>' +
      '</div></main>' + renderFooter();
  });

  document.getElementById('cancelPay').addEventListener('click', function() {
    initCheckoutPage();
  });
}"}

