          '<div class="product-info"><h3>' + p.name + '</h3><div class="price"><span class="current">' + formatPrice(p.price) + '</span></div></div></div>';
      }).join('');

      app.innerHTML = renderHeader() + '<main class="container"><div class="empty-cart"><div class="icon">🛒</div><h2>购物车是空的</h2><p style="color:var(--text-secondary);margin-bottom:20px">快去挑选心仪的商品吧</p><a href="index.html" class="btn btn-primary">去逛逛</a></div>' +
        '<div style="margin-top:60px"><h2 style="margin-bottom:20px">为您推荐</h2><div class="products-grid">' + recommendHtml + '</div></div></main>' + renderFooter();
      return;
    }

    // 初始化选中状态
    items.forEach(function(item) {
      if (selectedItems[item.id] === undefined) selectedItems[item.id] = true;
    });

    var selectedCount = items.filter(function(item) { return selectedItems[item.id]; }).length;
    var subtotal = items.reduce(function(s, item) {
      if (!selectedItems[item.id]) return s;
      var p = PRODUCTS.find(function(pr) { return pr.id === item.id; });
      return s + (p ? p.price * item.qty : 0);
    }, 0);
    var shipping = subtotal >= 199 ? 0 : 15;
    var total = subtotal + shipping;
    var allSelected = selectedCount === items.length;

    var headerHtml = '<div class="cart-header"><span><input type="checkbox" id="selectAll" ' + (allSelected ? 'checked' : '') + '> 全选</span><span>商品</span><span>单价</span><span>数量</span><span>小计</span><span>操作</span></div>';
    var itemsHtml = items.map(function(item) {
      var p = PRODUCTS.find(function(pr) { return pr.id === item.id; });
      if (!p) return '';
      var checked = selectedItems[item.id] ? 'checked' : '';
      return '<div class="cart-item' + (selectedItems[item.id] ? '' : ' unchecked') + '">' +
        '<div><input type="checkbox" class="item-checkbox" data-id="' + p.id + '" ' + checked + '></div>' +
        '<div class="item-product"><div class="item-img">' + p.image + '</div><div><div class="item-name">' + p.name + '</div><div class="item-stock">有货</div></div></div>' +
        '<div class="item-price">' + formatPrice(p.price) + '</div>' +
        '<div class="quantity-selector"><button onclick="Cart.updateQty(' + p.id + ',' + (item.qty - 1) + ');initCartPage()">−</button><span>' + item.qty + '</span><button onclick="Cart.updateQty(' + p.id + ',' + (item.qty + 1) + ');initCartPage()">+</button></div>' +
        '<div class="item-price" style="font-weight:600;color:var(--danger)">' + formatPrice(p.price * item.qty) + '</div>' +
        '<div class="item-actions"><button class="delete-btn" onclick="Cart.remove(' + p.id + ');delete selectedItems[' + p.id + '];initCartPage()">删除</button></div></div>';
    }).join('');

    app.innerHTML = renderHeader() +
      '<main class="container cart-page"><h1 class="page-title">🛒 购物车 <span style="font-size:1rem;color:var(--text-secondary)">(' + items.length + '件商品)</span></h1>' +
      '<div class="cart-toolbar"><button class="btn-link" id="clearCart">清空购物车</button></div>' +
      '<div class="checkout-grid"><div>' + headerHtml + itemsHtml + '</div>' +
      '<div class="cart-summary"><h3>订单摘要</h3>' +
      '<div class="summary-row"><span>已选商品</span><span>' + selectedCount + '件</span></div>' +
      '<div class="summary-row"><span>商品小计</span><span>' + formatPrice(subtotal) + '</span></div>' +
      '<div class="summary-row"><span>运费</span><span>' + (shipping === 0 ? '免运费' : formatPrice(shipping)) + '</span></div>' +
      '<div class="summary-row"><span style="font-size:0.8rem;color:var(--accent)">满199元免运费</span></div>' +
      '<div class="summary-row total"><span>总计</span><span>' + formatPrice(total) + '</span></div>' +
      '<button class="btn btn-primary btn-block" style="margin-top:20px" id="goCheckout">去结算 (' + selectedCount + '件)</button>' +
      '<a href="index.html" class="btn btn-secondary btn-block" style="margin-top:10px">继续购物</a>' +
      '</div></div></main>' + renderFooter();

    bindEvents();
  }

  function bindEvents() {
    // 全选按钮
    var selectAll = document.getElementById('selectAll');
    if (selectAll) {
      selectAll.addEventListener('change', function() {
        var checked = this.checked;
        Cart.getAll().forEach(function(item) { selectedItems[item.id] = checked; });
        render();
      });
    }

    // 单个商品选择
    document.querySelectorAll('.item-checkbox').forEach(function(cb) {
      cb.addEventListener('change', function() {
        selectedItems[parseInt(this.getAttribute('data-id'))] = this.checked;
        render();
      });
    });

    // 清空购物车
    var clearBtn = document.getElementById('clearCart');
    if (clearBtn) {
      clearBtn.addEventListener('click', function() {
        if (confirm('确定要清空购物车吗？')) {
          Cart.clear();
          selectedItems = {};
          render();
        }
      });
    }

    // 去结算
    var checkoutBtn = document.getElementById('goCheckout');
    if (checkoutBtn) {
      checkoutBtn.addEventListener('click', function() {
        var selected = Cart.getAll().filter(function(item) { return selectedItems[item.id]; });
        if (selected.length === 0) { showToast('请至少选择一件商品'); return; }
        // 保存选中商品到临时存储
        sessionStorage.setItem('checkout_items', JSON.stringify(selected));
        location.href = 'checkout.html';
      });
    }
  }

  render();
}"}

