 /* 支付方式选择 */
 .payment-options{display:flex;flex-direction:column;gap:12px;margin-top:15px}
 .payment-option{display:flex;align-items:center;gap:15px;padding:16px;border:2px solid var(--border);border-radius:var(--radius-sm);cursor:pointer;transition:var(--transition);background:var(--bg-card)}
 .payment-option:hover{border-color:var(--primary-light)}
